/**
 * Generate the next number with a given prefix for a given year.
 * Format: <prefix>-<year>-<counter> where counter is 4 digits zero-padded.
 * @param {Array<string>} existingNumbers - Array of existing numbers
 * @param {string} prefix - Prefix (e.g., "INV" or "CN")
 * @param {string} date - Date in YYYY-MM-DD format
 * @returns {string}
 */
export function nextNumber(existingNumbers, prefix, date) {
  const year = date.split('-')[0];
  const pattern = `${prefix}-${year}-`;

  const thisYearNumbers = existingNumbers
    .filter((num) => num.startsWith(pattern))
    .map((num) => {
      const counter = num.split('-')[2];
      return Number(counter);
    });

  const maxCounter = thisYearNumbers.length > 0 ? Math.max(...thisYearNumbers) : 0;
  const nextCounter = maxCounter + 1;

  return `${prefix}-${year}-${String(nextCounter).padStart(4, '0')}`;
}

/**
 * Generate the next invoice number for a given year.
 * Format: INV-<year>-<counter> where counter is 4 digits zero-padded.
 * @param {Array<string>} existingNumbers - Array of existing invoice numbers (e.g., ["INV-2024-0001"])
 * @param {string} issueDate - Issue date in YYYY-MM-DD format
 * @returns {string}
 */
export function nextInvoiceNumber(existingNumbers, issueDate) {
  return nextNumber(existingNumbers, 'INV', issueDate);
}

